import json, subprocess, hashlib, os, re
commits = subprocess.check_output(['git','log','--all','--format=%H','--','.omgithub/conversation.json'], text=True).split()
seen = {}
order = []
for c in commits:
    try:
        raw = subprocess.check_output(['git','show',f'{c}:.omgithub/conversation.json'], stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError:
        continue
    try:
        d = json.loads(raw)
    except Exception as e:
        continue
    msgs = d.get('messages', []) if isinstance(d,dict) else []
    for m in msgs:
        if m.get('type') != 'user': continue
        t = m.get('text')
        if not isinstance(t,str) or not t.strip(): continue
        # some texts are JSON-encoded strings
        s = t.strip()
        if s.startswith('"') and s.endswith('"'):
            try: s = json.loads(s)
            except Exception: pass
        h = hashlib.sha1(s.encode()).hexdigest()[:12]
        if h not in seen:
            seen[h] = {'hash':h,'commit':c,'text':s}
            order.append(h)
# sort by commit order (oldest last in list); keep as discovered (newest first)
out = [seen[h] for h in order]
json.dump(out, open('/tmp/opencode/user_msgs.json','w'), ensure_ascii=False, indent=1)
print('unique user msgs:', len(out))
for m in out:
    t = m['text'].replace('\n',' ')
    print(m['hash'], m['commit'][:7], len(m['text']), t[:160])
